#ifndef GUARD_CONSTANTS_ORCHID_UI_H
#define GUARD_CONSTANTS_ORCHID_UI_H

// Shared Orchid UI kit constants (see dev_scripts/orchid_ui/).

// Frames of graphics/interface/orchid_status_icons.png (16x16 each),
// generated by dev_scripts/orchid_ui/export_status.py.
enum OrchidStatusIcon
{
    ORCHID_STATUS_PSN,
    ORCHID_STATUS_TOX,
    ORCHID_STATUS_PAR,
    ORCHID_STATUS_SLP,
    ORCHID_STATUS_BRN,
    ORCHID_STATUS_FRZ,
    ORCHID_STATUS_FRB,
    ORCHID_STATUS_FNT,
    ORCHID_STATUS_PKRS,
    ORCHID_STATUS_COUNT,
    ORCHID_STATUS_NONE = 0xFF,
};

// Gender is shown by the name colour (no glyph). RGB, from battle_ext.NAME_MALE / NAME_FEMALE.
#define ORCHID_NAME_MALE_FG       RGB(5, 10, 23)    // (40, 80, 184)
#define ORCHID_NAME_MALE_SHADOW   RGB(21, 24, 29)   // (168, 192, 232)
#define ORCHID_NAME_FEMALE_FG     RGB(23, 6, 9)     // (184, 48, 72)
#define ORCHID_NAME_FEMALE_SHADOW RGB(29, 22, 23)   // (232, 176, 184)

#endif // GUARD_CONSTANTS_ORCHID_UI_H
